using BotSupport;
var count=0;
void Check(bool ok,string label) { if(!ok) throw new Exception(label); count++; Console.WriteLine("PASS "+label); }
foreach(var pair in new[] { ("Low",75),("Medium",85),("High",95) })
    Check(Enumerable.Range(0,100).Count(r => SupportPolicy.StopSucceeds(pair.Item1,r))==pair.Item2,pair.Item1+" exact chance out of 100");
Check(SupportPolicy.IsWeaponRequest("#Chatwheel_requestweapon"),"installed wheel token");
Check(SupportPolicy.IsWeaponRequest("CW.NeedWeapon"),"CW token");
Check(!SupportPolicy.IsWeaponRequest("#Chatwheel_followme"),"other radio commands untouched");
var rich = new[]{new Donor(1,10000,200),new Donor(2,12000,300)};
Check(SupportPolicy.Select(rich,2,"auto",0) is { } a && a.Donor.Slot==2 && a.Gun.Item=="weapon_awp","one richest donor, prefer AWP");
Check(SupportPolicy.Select([new(1,3200,100)],2,"auto",0)?.Gun.Item=="weapon_ak47","affordable main rifle before fallback");
Check(SupportPolicy.Select([new(1,3400,100)],3,"auto",0)?.Gun.Item=="weapon_m4a1_silencer","CT fallback excludes AUG");
Check(SupportPolicy.Select([new(1,4750,100)],2,"auto",0)?.Gun.Item=="weapon_awp","exact balance accepted");
Check(SupportPolicy.Select([new(1,1049,100)],2,"auto",0) == null,"below cheapest eligible gun rejected");
Check(SupportPolicy.Select([new(1,16000,1501)],2,"auto",0) == null,"distant donor rejected");
Check(SupportPolicy.Select(rich,3,"ak") == null,"wrong team weapon rejected");
Check(SupportPolicy.Select(rich,3,"m4a4")?.Gun is { Item:"weapon_m4a1", Price:2900 },"M4A4 item mapping and price");
Check(SupportPolicy.Select(rich,3,"m4a1")?.Gun.Item=="weapon_m4a1_silencer","M4A1-S item mapping");
Check(SupportPolicy.Select(rich,2,"awm")?.Gun.Item=="weapon_awp","AWM alias");
Check(SupportPolicy.Select([],2,"auto",0) == null,"no donor no weapon");
Check(SupportPolicy.Select([new(1,10000,400),new(2,10000,200)],2,"auto",0)?.Donor.Slot==2,"equal funds choose nearer donor");
Check(SupportPolicy.Select([new(1,10000,200),new(2,10000,200)],2,"auto",0)?.Donor.Slot==1,"equal funds and distance deterministic single donor");
Check(SupportPolicy.Select([new(1,1900,100)],2,"auto",0)?.Gun.Item=="weapon_galilar","Galil before cheaper SMGs");
Check(SupportPolicy.Select([new(1,2400,100)],3,"auto",0)?.Gun.Item=="weapon_famas","FAMAS preferred over more expensive P90");
Check(SupportPolicy.Select([new(1,1700,100)],2,"auto",0)?.Gun.Item=="weapon_mp7","highest priced affordable SMG");
Check(SupportPolicy.Select([new(1,1300,100)],3,"auto",0)?.Gun.Item=="weapon_bizon","Bizon above MP9 when affordable");
Check(SupportPolicy.Select([new(1,1250,100)],3,"auto",0)?.Gun.Item=="weapon_mp9","CT cheapest tiers");
Check(SupportPolicy.Select([new(1,1050,100)],2,"auto",0)?.Gun.Item=="weapon_mac10","spend exact low balance on MAC10");
Check(SupportPolicy.Select([new(1,2700,100)],2,"auto",0)?.Gun.Item=="weapon_ak47","AK affordable at exact balance");
Check(SupportPolicy.Select([new(1,2900,100)],3,"auto",0)?.Gun.Item=="weapon_m4a1_silencer","M4 at exact price");
Check(SupportPolicy.Select([new(1,1700,100)],2,"awp")?.Gun.Item=="weapon_mp7","specific request also falls back when unaffordable");
Check(SupportPolicy.Select([new(1,1500,100),new(2,1700,900)],2,"auto",0)?.Donor.Slot==2,"richest donor retained for fallback");
Check(!SupportPolicy.Guns(3,"auto").Any(g => g.Item=="weapon_aug"),"AUG absent from request list");
Check(Enumerable.Range(0,2).Select(i => SupportPolicy.Select(rich,2,"auto",i)!.Value.Gun.Item).ToHashSet().SetEquals(new[]{"weapon_awp","weapon_ak47"}),"T random pool has AWP and AK");
Check(Enumerable.Range(0,3).Select(i => SupportPolicy.Select(rich,3,"auto",i)!.Value.Gun.Item).ToHashSet().SetEquals(new[]{"weapon_awp","weapon_m4a1_silencer","weapon_m4a1"}),"CT random pool has AWP and both M4s");
Check(Enumerable.Range(0,10).All(i => SupportPolicy.Select([new(1,3000,100)],3,"auto",i)!.Value.Gun.Item!="weapon_awp"),"unaffordable AWP excluded from random pool");
Check(!SupportPolicy.Guns(2,"awp").Any(g=>g.Item is "weapon_aug" or "weapon_sg556"),"T donation fallback excludes scoped rifles");
Check(SupportPolicy.Select([new(1,4000,100)],2,"awp")?.Gun.Item=="weapon_ak47","unaffordable AWP falls back to AK rather than SG553");
Check(SupportPolicy.Select(rich,2,"auto",0,allowSniper:false)?.Gun.Item=="weapon_ak47","quota-full auto request chooses AK");
Check(SupportPolicy.Select(rich,3,"awp",allowSniper:false)?.Gun.Item=="weapon_m4a1_silencer","quota-full explicit AWP request falls back to M4");
Check(Enumerable.Range(0,20).All(i=>SupportPolicy.Select(rich,3,"auto",i,allowSniper:false)?.Gun.Item!="weapon_awp"),"random request cannot bypass quota");
Console.WriteLine($"{count} checks passed");

